<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Domain\Backup;use StudPulse\Domain\{GroupRating,UserAvatar};use StudPulse\Integrations\MpeiMailCache;use StudPulse\Security\Auth;final class PrivacyController{public function export(Auth$a):array{$a->browserOnly(true);return Backup::manifest($a);}public function erase(Auth$a,Request$r):array{$a->browserOnly(true);if(($r->body['confirmation']??'')!=='УДАЛИТЬ'){throw new ApiError(422,'CONFIRM_REQUIRED','Введите УДАЛИТЬ для подтверждения');}$u=$a->user['id'];DB::run("UPDATE users SET email=NULL,display_name='Удалённый пользователь',external_subject=NULL,provider=NULL,status='deleted',email_verified_at=NULL,university_verified_at=NULL,official_authorized_until=NULL WHERE id=?",[$u]);GroupRating::erase($u);UserAvatar::erase($u);MpeiMailCache::erase($u);foreach(['user_sessions','api_tokens','bars_accounts','provider_connections','oauth_states','google_connections','push_subscriptions','personal_notes','user_preferences','bars_academic_watch','notifications']as$table){$column=$table==='personal_notes'?'owner_user_id':($table==='notifications'?'recipient_user_id':'user_id');DB::run('DELETE FROM '.$table.' WHERE '.$column.'=?',[$u]);}DB::run('DELETE FROM google_drive_folders WHERE user_id=?',[$u]);DB::run('DELETE FROM google_drive_copies WHERE recipient_user_id=?',[$u]);DB::run('DELETE FROM official_grade_snapshots WHERE user_id=?',[$u]);DB::run('DELETE FROM official_attendance_snapshots WHERE user_id=?',[$u]);DB::run('DELETE FROM ranking_snapshots WHERE user_id=?',[$u]);DB::run('DELETE FROM bars_rating_points WHERE user_id=?',[$u]);DB::run('UPDATE materials SET deleted_at=UTC_TIMESTAMP(6) WHERE owner_user_id=?',[$u]);DB::run('UPDATE homework SET deleted_at=UTC_TIMESTAMP(6) WHERE author_user_id=?',[$u]);DB::run('UPDATE group_memberships SET valid_to=UTC_TIMESTAMP(6) WHERE user_id=? AND valid_to>UTC_TIMESTAMP(6)',[$u]);Auth::cookie('',time()-3600);return['deleted'=>true,'message'=>'Доступ отозван, персональный профиль обезличен. Приватные файлы удаляет задача retention; сроки описаны в политике.'];}}